import{c as a,Q as n,j as o,m as s}from"./chunks/framework.DVSyX6JR.js";const g=JSON.parse('{"title":"Regions","description":"","frontmatter":{},"headers":[],"relativePath":"docs/regions.md","filePath":"docs/regions.md"}'),i={name:"docs/regions.md"};function r(t,e,l,p,c,d){return n(),o("div",null,[...e[0]||(e[0]=[s(`<h1 id="regions" tabindex="-1">Regions <a class="header-anchor" href="#regions" aria-label="Permalink to &quot;Regions&quot;">​</a></h1><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h2><p>MeshCoreNG has two region-related features:</p><ul><li>A generated Dutch region database for looking up known MeshCore region codes.</li><li>A runtime region map for controlling which scopes a repeater should forward.</li></ul><p>The lookup database helps operators find correct codes. The runtime region map decides forwarding policy on a device.</p><h2 id="dutch-region-database" tabindex="-1">Dutch region database <a class="header-anchor" href="#dutch-region-database" aria-label="Permalink to &quot;Dutch region database&quot;">​</a></h2><p>The Dutch region database is generated from the Dutch MeshWiki region list and compiled into firmware flash. It is read-only at runtime and does not allocate a large RAM database.</p><p>Useful commands:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>regiondb info</span></span>
<span class="line"><span>regiondb provinces</span></span>
<span class="line"><span>regiondb find gron</span></span>
<span class="line"><span>regiondb get 45</span></span>
<span class="line"><span>regiondb code &lt;code_id&gt;</span></span></code></pre></div><p>This is useful for installers, companion apps and operators who need to choose a region code without carrying a separate lookup file.</p><h2 id="runtime-forwarding-regions" tabindex="-1">Runtime forwarding regions <a class="header-anchor" href="#runtime-forwarding-regions" aria-label="Permalink to &quot;Runtime forwarding regions&quot;">​</a></h2><p>Runtime regions are editable scopes such as <code>eu</code>, <code>nl</code>, <code>nl-nh</code> or a local town/area code.</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>region put eu</span></span>
<span class="line"><span>region put nl eu</span></span>
<span class="line"><span>region put nl-nh nl</span></span>
<span class="line"><span>region put nl-nh-bov nl-nh</span></span>
<span class="line"><span>region allowf nl-nh-bov</span></span>
<span class="line"><span>region home nl-nh-bov</span></span>
<span class="line"><span>region tree</span></span>
<span class="line"><span>region save</span></span></code></pre></div><p><code>allowf</code> means this repeater may forward flood traffic for that region. <code>denyf</code> blocks forwarding for that region. Use <code>region save</code> after changes so the map survives reboot.</p><h2 id="practical-guidance" tabindex="-1">Practical guidance <a class="header-anchor" href="#practical-guidance" aria-label="Permalink to &quot;Practical guidance&quot;">​</a></h2><p>Local repeaters should usually allow only their local scope. Backbone or high-site repeaters can intentionally allow broader scopes such as province, country or regional bridge groups.</p><p>Avoid enabling broad scopes everywhere. The point is to preserve RF airtime by keeping local traffic local and forwarding wide-area traffic only where it is actually needed.</p><h2 id="region-profiles" tabindex="-1">Region profiles <a class="header-anchor" href="#region-profiles" aria-label="Permalink to &quot;Region profiles&quot;">​</a></h2><p>Region profile support allows builds to ship with known defaults for a deployment. This is useful for community firmware images where devices should start with the correct regional assumptions while still allowing operators to inspect and adjust runtime policy.</p>`,19)])])}const u=a(i,[["render",r]]);export{g as __pageData,u as default};
